function summarize(n, depth, maxDepth) {
  const o = { id: n.id, name: n.name, type: n.type, x: Math.round((n.x||0)*10)/10, y: Math.round((n.y||0)*10)/10, w: Math.round((n.width||0)*10)/10, h: Math.round((n.height||0)*10)/10 };
  if (n.fills && n.fills.length) {
    o.fills = n.fills.map(f => f.type === "SOLID" ? `solid ${f.color.r? Math.round(f.color.r*255):0},${Math.round(f.color.g*255)},${Math.round(f.color.b*255)} a${f.opacity===undefined?1:f.opacity}` : f.type);
  }
  if (n.type === "TEXT") {
    o.chars = n.characters;
    o.font = n.fontName;
    o.fontSize = n.fontSize;
    o.color = n.fills && n.fills[0] && n.fills[0].type === "SOLID" ? `${Math.round(n.fills[0].color.r*255)},${Math.round(n.fills[0].color.g*255)},${Math.round(n.fills[0].color.b*255)}` : null;
  }
  if (n.type === "VECTOR" || n.type === "BOOLEAN_OPERATION") {
    o.strokes = n.strokes && n.strokes.length ? "yes" : "no";
  }
  if (depth < maxDepth && "children" in n) o.children = n.children.map(c => summarize(c, depth+1, maxDepth));
  return o;
}
