const F = {R:{family:"Inter",style:"Regular"},M:{family:"Inter",style:"Medium"},SB:{family:"Inter",style:"Semi Bold"},B:{family:"Inter",style:"Bold"},EB:{family:"Inter",style:"Extra Bold"}};
function rgb(h){return {r:parseInt(h.slice(1,3),16)/255,g:parseInt(h.slice(3,5),16)/255,b:parseInt(h.slice(5,7),16)/255};}
function P(h,o){return {type:"SOLID",color:rgb(h),opacity:o===undefined?1:o};}
function T(parent,name,chars,o){
  o=o||{}; const t=figma.createText();
  t.fontName=F[o.w||"R"]; t.fontSize=o.s||15; t.characters=chars;
  t.fills=[P(o.c||"#101C2B",o.op)];
  t.lineHeight={unit:"PIXELS",value:o.lh||Math.round((o.s||15)*1.45)};
  t.name=name; parent.appendChild(t);
  if(o.wd){ t.textAutoResize="HEIGHT"; t.resize(o.wd,o.lh||20); t.textAlignHorizontal=o.al||"LEFT"; }
  else t.textAutoResize="WIDTH_AND_HEIGHT";
  return t;
}
function box(parent,name,w,h,x,y,fill,rad){
  const f=figma.createFrame(); f.name=name; f.resize(w,h); parent.appendChild(f);
  f.x=x||0; f.y=y||0; f.fills=fill?[P(fill)]:[]; f.cornerRadius=rad===undefined?0:rad; f.clipsContent=false;
  return f;
}
function icon(parent,compId,size,color,x,y,name){
  const inst=figma.getNodeById(compId).createInstance(); parent.appendChild(inst);
  inst.rescale(size/inst.width);
  inst.findAll(n=>n.type==="VECTOR").forEach(v=>{ if(v.fills&&v.fills.length) v.fills=[P(color)]; if(v.strokes&&v.strokes.length) v.strokes=[P(color)]; });
  inst.x=x===undefined?0:x; inst.y=y===undefined?0:y; if(name) inst.name=name;
  return inst;
}
